head.script:

scwin.checkVal1 = function() {
	return WebSquare.WebSquaredoc.models[0].submissions[0].id == 'mf_w1_submission2';
}		
scwin.checkVal2 = function() {
	return WebSquare.WebSquaredoc.models [0] .submissions.toString() == '[object Object]';
}

scwin.checkVal3 = function() {
	return WebSquare.wUnit.getJq('#w1_wgridView1_body_tbody tr').not('.w2grid_hidedRow').length != 0;
}		
scwin.checkVal4 = function() {
	return WebSquare.wUnit.getJq('#w1_wgridView2_body_tbody tr').not('.w2grid_hidedRow').length != 0;
}			

scwin.checkVal5 = function() {
	return WebSquare.WebSquaredoc.models[0].submissions.length == 0;
}		
scwin.checkVal6 = function() {
	return WebSquare.WebSquaredoc.models[0].submissions.toString() == '';
}			

scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('w1_trigger2').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('w1_trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('w1_trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('w1_trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal5()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal6()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
}
